const input = $input.item.json.body ?? $input.item.json;
const uuid = /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i;
const idempotencyKey = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/;
const templateTypeCodes = new Map([
  [String.fromCodePoint(0x611f, 0x6027, 0x6587, 0x5b57), 'emotive_text'],
  [String.fromCodePoint(0x7b80, 0x5355, 0x903b, 0x8f91), 'simple_logic'],
  [String.fromCodePoint(0x91cd, 0x590d, 0x6307, 0x4ee4), 'repeated_instruction'],
  [String.fromCodePoint(0x590d, 0x6742, 0x4efb, 0x52a1), 'complex_task'],
  [String.fromCodePoint(0x5ba2, 0x89c2, 0x516c, 0x6b63), 'objective_fair']
]);
const templateCodeFor = (value) => templateTypeCodes.get(value);
const defaultCredentialReference = 'n8n-credential:openai-account-v1';
const credentialReferences = new Set([defaultCredentialReference, 'n8n-credential:relaycove-v1']);
const fail = (code, message) => [{ json: { route: 'respond', result: { ok: false, error: { code, message } } } }];
const hasOnly = (allowed) => Object.keys(input).every((key) => allowed.has(key));
const text = (value) => typeof value === 'string' && value.trim() !== '';
const object = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const base = new Set(['action', 'local_operator_id']);
const readonlyBudget = ['token_budget', 'token_budget_version'];
const modelFieldsProvided = () => input.provider_base_url !== undefined || input.model_name !== undefined || input.api_key_ref !== undefined;
const validModelFields = () => text(input.provider_base_url) && text(input.model_name) && credentialReferences.has(input.api_key_ref);
const normalizedModelFields = () => ({
  provider_base_url: input.provider_base_url.trim(),
  model_name: input.model_name.trim(),
  api_key_ref: input.api_key_ref
});
if (!object(input) || !text(input.action)) return fail('INVALID_REQUEST', '请求格式无效。');
if (input.action === 'operator') {
  const allowed = new Set(['action', 'local_operator_id']);
  if (!hasOnly(allowed) || (input.local_operator_id !== undefined && (!text(input.local_operator_id) || !uuid.test(input.local_operator_id)))) return fail('INVALID_REQUEST', '本地操作者标识无效。');
  return [{ json: { route: 'db', request: input } }];
}
if (!text(input.local_operator_id) || !uuid.test(input.local_operator_id)) return fail('INVALID_REQUEST', '请求格式或本地操作者标识无效。');
if (input.action === 'read') {
  const allowed = new Set([...base, 'book_id', 'node_code']);
  if (!hasOnly(allowed) || (input.book_id !== undefined && (!text(input.book_id) || !uuid.test(input.book_id))) || (input.node_code !== undefined && !text(input.node_code))) return fail('INVALID_REQUEST', '读取配置时只能提交有效的作品或节点范围。');
  return [{ json: { route: 'db', request: input } }];
}
if (input.action === 'book_banner') {
  const allowed = new Set([...base, 'book_id']);
  if (!hasOnly(allowed) || !text(input.book_id) || !uuid.test(input.book_id)) return fail('INVALID_REQUEST', '读取作品横幅需要有效的作品范围。');
  return [{ json: { route: 'db', request: input } }];
}
if (input.action === 'save_prompt_active') {
  const allowed = new Set([...base, 'fp_target', 'prompt_text', 'idempotency_key', ...readonlyBudget]);
  if (!hasOnly(allowed) || !text(input.fp_target) || !text(input.prompt_text) || !text(input.idempotency_key) || !idempotencyKey.test(input.idempotency_key)) return fail('INVALID_REQUEST', '保存 Prompt 需要节点、完整文本和有效的幂等键。');
  return [{ json: { route: 'db', request: input } }];
}
if (input.action === 'save_model_template') {
  const allowed = new Set([...base, 'template_type', 'provider_base_url', 'model_name', 'api_key_ref', 'connection_test_evidence_id', 'routing_config_jsonb', 'parameters_jsonb', 'idempotency_key', ...readonlyBudget]);
  const templateCode = templateCodeFor(input.template_type);
  if (!hasOnly(allowed) || !templateCode || (modelFieldsProvided() && !validModelFields()) || !text(input.connection_test_evidence_id) || !uuid.test(input.connection_test_evidence_id) || !text(input.idempotency_key) || !idempotencyKey.test(input.idempotency_key) || (input.routing_config_jsonb !== undefined && !object(input.routing_config_jsonb)) || (input.parameters_jsonb !== undefined && !object(input.parameters_jsonb))) return fail('INVALID_REQUEST', '保存模型模板需要有效模板、受控测试证据和幂等键；模型地址与密钥引用由后端证据解析。');
  return [{ json: { route: 'db', request: { ...input, ...(modelFieldsProvided() ? normalizedModelFields() : {}), template_type: templateCode } } }];
}
if (input.action === 'bind_node_template') {
  const allowed = new Set([...base, 'node_code', 'template_type', 'temperature', 'idempotency_key', ...readonlyBudget]);
  const templateCode = templateCodeFor(input.template_type);
  if (!hasOnly(allowed) || !text(input.node_code) || !templateCode || !text(input.idempotency_key) || !idempotencyKey.test(input.idempotency_key) || (input.temperature !== undefined && (typeof input.temperature !== 'number' || !Number.isFinite(input.temperature) || input.temperature < 0 || input.temperature > 2))) return fail('INVALID_REQUEST', '绑定节点模板需要有效节点、模板、温度和幂等键。');
  return [{ json: { route: 'db', request: { ...input, template_type: templateCode } } }];
}
if (input.action === 'save_book_config') {
  const allowed = new Set([...base, 'book_id', 'auto_production', 'auto_audit', 'auto_iteration', 'presentation_intensity', 'idempotency_key', ...readonlyBudget]);
  if (!hasOnly(allowed) || !text(input.book_id) || !uuid.test(input.book_id) || typeof input.auto_production !== 'boolean' || typeof input.auto_audit !== 'boolean' || typeof input.auto_iteration !== 'boolean' || typeof input.presentation_intensity !== 'number' || !Number.isFinite(input.presentation_intensity) || input.presentation_intensity < 0 || input.presentation_intensity > 1 || !text(input.idempotency_key) || !idempotencyKey.test(input.idempotency_key)) return fail('INVALID_REQUEST', '保存作品配置需要作品范围、三项自动化、表现参数和幂等键。');
  return [{ json: { route: 'db', request: input } }];
}
if (input.action === 'test_connection') {
  const allowed = new Set([...base, 'template_type', 'provider_base_url', 'model_name', 'api_key_ref']);
  const templateCode = templateCodeFor(input.template_type);
  const requestedCredentialReference = input.api_key_ref === undefined ? defaultCredentialReference : input.api_key_ref;
  if (!hasOnly(allowed) || !templateCode || !text(input.provider_base_url) || !text(input.model_name) || !credentialReferences.has(requestedCredentialReference)) return fail('INVALID_REQUEST', 'Controlled connection testing requires an approved deployment credential reference.');
  return [{ json: { route: 'db', request: {
    action: 'test_connection',
    local_operator_id: input.local_operator_id,
    template_type: templateCode,
    provider_base_url: input.provider_base_url.trim(),
    model_name: input.model_name.trim(),
    api_key_ref: requestedCredentialReference
  } } }];
}
return fail('INVALID_REQUEST', '请求操作不受支持。');
